from hdr import *
r.append(R(7483758,"भुना हुआ चिकोरी",
"सब्ज़ी की एक बहुमुखी साइड डिश, खासकर सर्दियों में बढ़िया।",
"2","246 ग्राम",
["6 चिकोरी के सिर (हेड)","2 कटी हुई लहसुन की फांकें","1 बड़ा चम्मच ऑलिव ऑयल","एक नींबू का छिलका और रस","25 ग्राम भुने हुए पाइन नट्स और कटा हुआ अजमोदा (पार्सले), परोसने के लिए"],
["चिकोरी को आधा काटें और धातु रहित (नॉन-मेटैलिक) रोस्टिंग डिश में रखें।","ऊपर से कटी हुई लहसुन की फांकें छिड़कें और ऑलिव ऑयल की धार डालें।","नींबू का छिलका और रस डालें।","200ºC/गैस 6 पर 25–30 मिनट तक भूनें जब तक नरम न हो जाए और हल्का जलने न लगे, फिर ऊपर से भुने हुए पाइन नट्स और कटा हुआ अजमोदा बिखेरें।"],
["पाइन नट्स को भूनने के लिए उन्हें सूखे फ्राइंग पैन में डालें और बार-बार पलटते हुए 2-3 मिनट पकाएँ। जैसे ही वे भूरे होने लगें, पैन से निकाल लें क्योंकि वे जल्दी जल जाते हैं।","आप इस रेसिपी को आधे कटे सौंफ़ के कंद (फ़ेनल बल्ब) से भी बना सकते हैं, जो कम कड़वे होते हैं।",fv(1)]))
r.append(R(7485658,"मैकरोनी चीज़",
"स्किम्ड दूध और कम वसा वाला चेडर, साथ में डाली गई सब्ज़ियाँ, इसे कम वसा वाला, ज़्यादा स्वादिष्ट और बेहतर संतुलित व्यंजन बनाती हैं।",
"2","461 ग्राम",
["1 छोटा चम्मच रेपसीड तेल","2 मध्यम प्याज़, बारीक कटे हुए","1 लीक, 0.5 सेमी मोटे छल्लों में कटी हुई","1 बड़ा चम्मच साबुत गेहूँ का आटा","1 छोटा चम्मच डिजॉन सरसों","200 मिलीलीटर स्किम्ड दूध","50 ग्राम आधी वसा वाला चेडर, कद्दूकस किया हुआ","100 ग्राम फ्रोज़न मटर, डीफ़्रॉस्ट किए हुए","100 ग्राम साबुत गेहूँ की मैकरोनी, पैकेट के निर्देशों के अनुसार पकाई और छानी हुई"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। सॉसपैन में तेल गरम करें और प्याज़ को 4-5 मिनट तक नरम होने तक भूनें, लेकिन भूरा न होने दें। लीक डालें और 3-4 मिनट और पकाएँ।","आटे को प्याज़ और लीक पर छिड़कें। अच्छी तरह मिलाएँ। सरसों डालें और फिर से मिलाएँ।","धीरे-धीरे दूध मिलाएँ और 2-3 मिनट चलाते रहें जब तक सॉस गाढ़ा न हो जाए।","चेडर का तीन-चौथाई हिस्सा डालें और तब तक चलाएँ जब तक वह घुल न जाए, मटर मिलाएँ और आँच से उतार लें।","मैकरोनी को सॉस में मिलाएँ, ओवन-प्रूफ़ डिश में डालें और बचा हुआ चेडर ऊपर छिड़कें। 20 मिनट बेक करें।"],
["अतिरिक्त फाइबर के लिए आप साबुत गेहूँ का पास्ता इस्तेमाल कर सकते हैं – यदि सुपरमार्केट में न मिले तो यह हेल्थ शॉप्स में उपलब्ध है। लेकिन साबुत गेहूँ की पेन्ने या कोई भी पास्ता शेप भी चलेगी।","आप स्वीटकॉर्न या पके हुए मशरूम, फूलगोभी या ब्रोकली डाल सकते हैं।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फ्रिज या माइक्रोवेव में डीफ़्रॉस्ट करें और अंदर तक गरम होने तक दोबारा गरम करें।",fv(3)]))
r.append(R(7485752,"एक ही ट्रे में एशियाई सैल्मन और ब्रोकली ट्रेबेक",
"प्रोटीन का स्रोत और ओमेगा-3 से भरपूर, यह सैल्मन और ब्रोकली ट्रेबेक सप्ताह के बीच के दिनों के लिए एक आदर्श व्यंजन है।",
"4","245 ग्राम",
["5 सेमी ताज़ा अदरक का टुकड़ा, छिला और कद्दूकस किया हुआ","1 लाल मिर्च, बीज निकालकर आधी करके पतली कटी हुई","4 बिना त्वचा के सैल्मन फ़िलेट (कुल वज़न 480 ग्राम)","400 ग्राम टेंडरस्टेम ब्रोकली","8 हरे प्याज़, छँटे हुए और हर एक 3 टुकड़ों में कटा हुआ","3 लहसुन की फांकें, कुचली हुई","2 छोटे चम्मच कम नमक वाला सोया सॉस","1 बड़ा चम्मच राइस वाइन सिरका","1 कैल तेल स्प्रे"],
["एक बड़ी छिछली डिश में लहसुन, अदरक, मिर्च, सोया सॉस और सिरका मिलाएँ। सैल्मन डालें और यदि समय हो तो रात भर, या कम से कम 20 मिनट मैरीनेट होने दें।","ओवन को 200°C/गैस 6 पर पहले से गरम करें। एक छिछली रोस्टिंग टिन पर कम कैलोरी वाला कुकिंग स्प्रे छिड़कें और ऊपर ब्रोकली और हरे प्याज़ सजाएँ। इसके बाद, सब्ज़ियों पर थोड़ा कम कैलोरी वाला कुकिंग स्प्रे छिड़कें। 10 मिनट पकाएँ।","ऊपर सैल्मन सजाएँ और मैरिनेड की धार डालें। ताज़ी पिसी काली मिर्च से स्वाद बढ़ाएँ। 12–15 मिनट पकाएँ जब तक सैल्मन अंदर तक पक न जाए। तुरंत परोसें।"],
[fv(1)]))
r.append(R(7489290,"मूसाका",
"पारंपरिक गाढ़ी टमाटर सॉस में हमने अतिरिक्त सब्ज़ियाँ मिलाई हैं ताकि पौष्टिकता और स्वाद बढ़े।",
"6","325 ग्राम",
["3 बैंगन, पतले कटे हुए (लगभग 3/4 सेमी)","1 छोटा चम्मच रेपसीड तेल","2 मध्यम प्याज़, बारीक कटे हुए","500 ग्राम दुबला बीफ़ कीमा","1 लाल शिमला मिर्च, बारीक कटी हुई","1 गाजर, कद्दूकस की हुई","3 फांक लहसुन, कटा हुआ","400 ग्राम का डिब्बा टमाटर","1 बड़ा चम्मच टमाटर प्यूरी","1 छोटा चम्मच ओरेगैनो","1 छोटा चम्मच पिसी दालचीनी","1 कम नमक वाला बीफ़ स्टॉक क्यूब, 100 मिलीलीटर उबलते पानी में घोला हुआ",["टॉपिंग के लिए","200 ग्राम 0% वसा वाला ग्रीक दही"],["टॉपिंग के लिए","50 ग्राम कम वसा वाला चेडर, बारीक कद्दूकस किया हुआ"],["टॉपिंग के लिए","1 ढेर वाला छोटा चम्मच पिसा जायफल"]],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। बैंगन के स्लाइस को हर तरफ़ 3-4 मिनट ग्रिल करें और एक तरफ़ रख दें।","पैन में तेल गरम करें और प्याज़ डालें। जब वे भूरे होने लगें, तो बीफ़ कीमा डालें और 5 मिनट चलाएँ, लकड़ी के चम्मच से गाँठों को तोड़ते हुए।","लाल शिमला मिर्च और गाजर डालें और 5 मिनट पकाएँ, फिर लहसुन, टमाटर, प्यूरी, ओरेगैनो और दालचीनी मिलाएँ।","स्टॉक मिलाएँ, उबाल आने दें फिर आँच धीमी करें, ढक दें और 10-15 मिनट धीमी आँच पर पकाएँ।","इसी बीच, टॉपिंग के लिए दही, चेडर और जायफल को एक साथ मिलाएँ।","ओवन-प्रूफ़ डिश में बैंगन की एक परत रखें, एक चम्मच बीफ़ का मिश्रण डालें, फिर बारी-बारी से परतें लगाएँ, आख़िर में बैंगन की परत रखें।","दही का मिश्रण ऊपर से चम्मच से डालें और 45 मिनट बेक करें।"],
["परोसने से पहले 15-20 मिनट ठंडा होने के लिए छोड़ दें।","मूसाका अक्सर मेमने के कीमे से बनाया जाता है। कम वसा वाले संस्करण के लिए इसकी जगह टर्की का कीमा इस्तेमाल करें।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फ्रिज या माइक्रोवेव में डीफ़्रॉस्ट करें और अंदर तक गरम होने तक दोबारा गरम करें।",fv(2)]))
r.append(R(7492878,"सब्ज़ी पकोड़े",
"ताज़ी, हल्की डिप के साथ स्वादिष्ट सब्ज़ी पकोड़ों का एक हल्के मसालेदार, निवाले के आकार का चयन।",
"10","105 ग्राम",
[["सब्ज़ियों के लिए","1 लाल शिमला मिर्च, टुकड़ों में कटी हुई"],["सब्ज़ियों के लिए","1 तोरी (कूजेट), लंबी डंडियों में कटी हुई"],["सब्ज़ियों के लिए","1 लाल प्याज़, फाँकों में कटा हुआ"],["सब्ज़ियों के लिए","200 ग्राम फूलगोभी, फूलों के रूप में"],["डिप के लिए","50 ग्राम ताज़ा धनिया, बारीक कटा हुआ"],["डिप के लिए","1 छोटा चम्मच जीरा, हल्का कुचला हुआ"],["डिप के लिए","150 ग्राम 0% वसा वाला सादा दही"],["घोल के लिए","100 ग्राम बेसन"],["घोल के लिए","1 छोटा चम्मच पिसा धनिया"],["घोल के लिए","1 छोटा चम्मच पिसी हल्दी"],["घोल के लिए","1 छोटा चम्मच गरम मसाला"],["घोल के लिए","1 छोटा चम्मच पिसा जीरा"],["घोल के लिए","1 हरी मिर्च, बारीक कटी हुई"],["घोल के लिए","1/2 छोटा चम्मच बेकिंग सोडा"],["घोल के लिए","100 मिलीलीटर पानी"],["घोल के लिए","400 मिलीलीटर रेपसीड तेल"]],
["सभी सब्ज़ियाँ तैयार करें। (प्याज़ तैयार करते समय, छिलका उतारें और केवल सिरों को सावधानी से काटें, क्योंकि जड़ को बरकरार रखने से फाँकें आपस में जुड़ी रहती हैं।)","एक डिश में डिप की सारी सामग्री को एक साथ मिलाएँ और फ्रिज में रख दें।","बेसन, सारे मसाले, मिर्च और बेकिंग सोडा को एक कटोरे में मिलाएँ, फिर पानी मिलाएँ। घोल गाढ़ी मलाई जैसा होना चाहिए।","एक सॉसपैन में तेल को 180°C तक गरम करें। यदि आपके पास थर्मामीटर नहीं है, तो तेल को घोल की एक छोटी बूँद से जाँचें। (यदि तेल पर्याप्त गरम है, तो घोल तुरंत तलने लगना चाहिए और ऊपर तैर आना चाहिए।)","सब्ज़ियों को घोल में डालें और उन्हें चारों ओर मिलाएँ ताकि सब पर परत चढ़ जाए। चम्मच से उन्हें निकालें और गरम तेल में सावधानी से डालें – एक बार में कुछ ही। पकोड़ों को 3–4 मिनट पकाएँ।","जब सुनहरे भूरे हो जाएँ, तो छेदवाले चम्मच से पकोड़े निकालें और निथारने के लिए किचन पेपर पर रखें। सारे पकोड़े पकने तक दोहराएँ। डिप के साथ परोसें।"],
["क्योंकि पकोड़े तले जाते हैं, इन्हें कभी-कभार के ट्रीट के रूप में ही लेना चाहिए।","यह सुनिश्चित करने के लिए कि पकोड़े बहुत चिकने न हों, तेल पर्याप्त गरम होना चाहिए – इस मामले में, 180ºC। इस तरह, पकाने का समय कम होगा और सब्ज़ियाँ तेल में ज़्यादा देर नहीं रहेंगी। कुक का थर्मामीटर इस्तेमाल करना यह पक्का करने का अच्छा तरीका है कि तेल सही तापमान पर है।","वसा की मात्रा कम करने के लिए बेक किए हुए पकोड़ों की रेसिपी इस्तेमाल करना संभव है, लेकिन इसके लिए सब्ज़ियों के बड़े टुकड़े और गाढ़ा घोल चाहिए। इस तरह, पकोड़े बेहतर तरीके से जुड़े रहेंगे।","सुनिश्चित करें कि आप सही प्रकार का तेल इस्तेमाल करें – और घी या चर्बी (ड्रिपिंग) से बचें। रेपसीड तेल का इस्तेमाल करें, क्योंकि यह पकाने की प्रक्रिया के लिए बेहतर है और असंतृप्त वसा है। ऑलिव ऑयल तलने के लिए उपयुक्त नहीं है।","आप इस घोल में ज़्यादातर सब्ज़ियाँ इस्तेमाल कर सकते हैं – ब्रोकली, बैंगन, गाजर की डंडियाँ, हरा प्याज़, शतावरी, बेबी कॉर्न या मशरूम आज़माएँ।"]))
r.append(R(7493654,"फलों वाला फ्रेंच टोस्ट",
"मौसमी फलों के कॉम्पोट के साथ साबुत गेहूँ की अंडे वाली ब्रेड।",
"2","237 ग्राम",
["1 बड़ा चम्मच पानी","100 ग्राम फ्रोज़न मिली-जुली बेरीज़","1 सेब, छिला और कद्दूकस किया हुआ","2 फ्री-रेंज अंडे","1 बड़ा चम्मच स्किम्ड दूध","2 मोटे स्लाइस साबुत गेहूँ की ब्रेड (प्रत्येक 40 ग्राम), तिरछे आधे कटे हुए","1 छोटा चम्मच सूरजमुखी तेल"],
["पानी और फ्रोज़न फलों को एक पैन में डालें और मध्यम आँच पर 2-3 मिनट पकाएँ जब तक वे गरम न हो जाएँ। सेब मिलाएँ और आँच से उतार लें।","इसी बीच, अंडे और दूध को एक साथ फेंटें, फिर ब्रेड के स्लाइस को अंडे के मिश्रण में 2-3 मिनट भिगोएँ। ब्रेड को दो-एक बार पलटें ताकि सारा तरल सोख लिया जाए।","एक नॉन-स्टिक फ्राइंग पैन में तेल गरम करें, ब्रेड के स्लाइस डालें, और धीमी आँच पर पकाएँ। ब्रेड को दो-एक बार पलटें जब तक दोनों तरफ़ सुनहरी भूरी न हो जाए। इसमें कुल लगभग 8 मिनट लगने चाहिए।","ऊपर फलों के साथ परोसें।"],
["टॉपिंग के लिए आप अपनी पसंद का कोई भी फल इस्तेमाल कर सकते हैं - नाशपाती और ब्लैकबेरी विशेष रूप से स्वादिष्ट होती हैं।","अतिरिक्त स्वाद के लिए दालचीनी या जायफल छिड़कें।","फलों की जगह ग्रिल किए मशरूम या टमाटर के साथ आप नमकीन संस्करण भी बना सकते हैं।",fv(1)]))
r.append(R(7493655,"फो",
"नूडल्स, सब्ज़ियों और चिकन के साथ वियतनामी सूप, मसालेदार शोरबे में – एक कटोरे में स्वादिष्ट भोजन।",
"4","423 ग्राम",
["2 छोटे चम्मच रेपसीड तेल","1 प्याज़, बारीक कटा हुआ","5 सेमी ताज़ा अदरक, बारीक कटा हुआ","4 फांक लहसुन, पतला कटा हुआ","2 चक्र फूल (स्टार ऐनीज़)","5 सेमी दालचीनी की डंडी","1/2 छोटा चम्मच धनिया के बीज","1 बर्ड्स आई मिर्च, चीरी हुई, और सजाने के लिए 4","1 चिकन ब्रेस्ट, बिना हड्डी और बिना त्वचा का","1 कम नमक वाला चिकन स्टॉक क्यूब, 600 मिलीलीटर उबलते पानी में","1 ब्रोकली, फूलों में तोड़ी हुई","1 गाजर, वेजिटेबल पीलर से रिबन के रूप में कटी हुई","300 ग्राम पहले से पके चावल के नूडल्स","300 ग्राम बीनस्प्राउट्स (अंकुरित दालें)","1 गुच्छा हरा प्याज़, कटा हुआ","30 ग्राम ताज़ा धनिया, मोटा कटा हुआ","1 नींबू (लाइम), परोसने के लिए"],
["पैन में तेल और प्याज़ डालें और 4-5 मिनट पकाएँ। अच्छी तरह भूरा होने तक बीच-बीच में चलाते रहें।","अदरक और लहसुन डालें और 2-3 मिनट और पकाएँ।","स्टार ऐनीज़, दालचीनी, धनिया के बीज, मिर्च और चिकन ब्रेस्ट डालें। अच्छी तरह मिलाएँ और 3-4 मिनट पकाएँ, यह सुनिश्चित करते हुए कि चिकन ब्रेस्ट हल्का भूरा हो जाए और मसालों में लिपट जाए।","स्टॉक मिलाएँ और फिर से अच्छी तरह मिलाएँ। उबाल आने दें, फिर आँच धीमी करें। ढक दें, फिर 15 मिनट धीमी आँच पर पकाएँ।","मिर्च, दालचीनी की डंडी और स्टार ऐनीज़ निकालकर फेंक दें। चिकन ब्रेस्ट निकालें और एक तरफ़ रख दें।","ब्रोकली डालें और 5 मिनट पकाएँ, फिर गाजर डालें और 2 मिनट और पकाएँ, उसके बाद नूडल्स और बीनस्प्राउट्स डालें। उबाल आने दें, फिर 4 कटोरों में बाँट दें।","चिकन को काटें और हर कटोरे के ऊपर कुछ रखें, फिर हरा प्याज़, धनिया, एक मिर्च और ताज़े नींबू का निचोड़ा हुआ रस डालें।"],
["आप चिकन की जगह पोर्क डाल सकते हैं, या ब्रोकली के साथ झींगे डाल सकते हैं।","वीगन संस्करण के लिए, चिकन की जगह टोफू इस्तेमाल करें और वेजिटेबल स्टॉक क्यूब इस्तेमाल करें।","ग्लूटेन-मुक्त संस्करण के लिए, ग्लूटेन-मुक्त स्टॉक क्यूब इस्तेमाल करें।",fv(2)]))
r.append(R(7494114,"पालक और पाइन नट्स के साथ पुदीना वाला बैंगन",
"ताज़े पुदीने के साथ चारग्रिल किए बैंगन और तोरी, बाल्सामिक सिरके में मैरीनेट किए हुए। एक सुरुचिपूर्ण सलाद जो इतना आसान है कि रोज़ बनाया जा सकता है।",
"4","350 ग्राम",
["2 बैंगन (550 ग्राम), कटे हुए","2 तोरी (360 ग्राम), लंबाई में कटी हुई","1 बड़ा चम्मच बाल्सामिक सिरका","10 ग्राम पुदीना, बारीक कतरा हुआ","1 बड़ा चम्मच एक्स्ट्रा-वर्जिन ऑलिव ऑयल","अच्छी तरह पिसी काली मिर्च","1 बड़ा चम्मच पाइन नट्स","1 x 80 ग्राम का ताज़ा रॉकेट (अरुगुला) का बैग","1 x 400 ग्राम का डिब्बा कैनेलिनी बीन्स, छानी हुई (छानने के बाद 240 ग्राम वज़न)","1 छोटा लाल प्याज़ (120 ग्राम), बहुत पतला कटा हुआ"],
["बैंगन के स्लाइस और तोरी को चारग्रिल या ग्रिल करें, हर तरफ़ 3-4 मिनट, फिर अलग रख दें और गरम रखें।","बाल्सामिक सिरका, पुदीना, ऑलिव ऑयल और काली मिर्च को एक साथ मिलाएँ और एक तरफ़ रख दें।","बैंगन और तोरी को तेल और सिरके के मिश्रण में मिलाएँ और अलग रख दें।","इसी बीच, पाइन नट्स को मध्यम आँच पर सूखे पैन में डालें। भूरे होने लगने तक भूनें, फिर आँच से उतारें और एक तरफ़ रख दें।","रॉकेट को परोसने की प्लेट पर रखें और ऊपर बैंगन और तोरी रखें। ऊपर से बीन्स, प्याज़ और पाइन नट्स बिखेरें।"],
["थोड़े कद्दूकस किए चीज़ के साथ पिटा ब्रेड में परोसकर देखें।","आप अपनी पसंद की कोई भी बीन्स इस्तेमाल कर सकते हैं, या फ्रोज़न छोटी ब्रॉड बीन्स के साथ आज़माएँ।",fv(4)]))
r.append(R(7496258,"सैल्मन पाते",
"आसानी से बनने वाला पाते जो पार्टी के लिए बढ़िया भोजन है।",
"2","224 ग्राम",
["212 ग्राम का डिब्बा जंगली पैसिफ़िक पिंक सैल्मन","4 हरे प्याज़, बारीक कटे हुए","1 बड़ा चम्मच केपर्स, धोए और मोटे कटे हुए","1/2 लाल शिमला मिर्च, बारीक कटी हुई","5 सेमी खीरा, बीज निकालकर बारीक कटा हुआ","1 बड़ा चम्मच बारीक कटा ताज़ा सोआ (डिल)/अजमोदा (पार्सले), साथ में परोसने के लिए एक टहनी","आधे नींबू का रस","अच्छी बड़ी चुटकी सफ़ेद मिर्च","25 ग्राम कम वसा वाला क्रीम चीज़"],
["सैल्मन से त्वचा हटाएँ लेकिन काँटे (हड्डियाँ) रहने दें। कटोरे में डालें, फिर क्रीम चीज़ को छोड़कर सारी सामग्री मिलाएँ और अच्छी तरह मिलाएँ।","क्रीम चीज़ मिलाएँ, फिर से मिलाएँ और ऊपर सोआ की एक टहनी रखकर परोसें।","साबुत अनाज के टोस्ट के छोटे चौकोर टुकड़ों के साथ परोसें।"],
["टोस्ट पर लगाने, रैप में लपेटने या शानदार सैंडविच के लिए आदर्श।","डिप के रूप में इस्तेमाल करने के लिए थोड़ा ग्रीक दही मिलाएँ।","1 छोटा चम्मच स्मोक्ड पपरिका या मिर्च मसाले से इसे मसालेदार बनाएँ।"]))
r.append(R(7497836,"सब्ज़ी सते",
"मसालेदार मूँगफली की सॉस और खुशबूदार सलाद के साथ भुनी सब्ज़ियों का इंद्रधनुष।",
"2","718 ग्राम",
["2 छोटे चम्मच रेपसीड तेल","1 लाल शिमला मिर्च, 6 फाँकों में कटी हुई","1 हरी शिमला मिर्च, 6 फाँकों में कटी हुई","1 तोरी (कूजेट), टुकड़ों में कटी हुई","1 बैंगन, टुकड़ों में कटा हुआ","2 लाल प्याज़, 6 फाँकों में कटे हुए","1 छोटा चम्मच पिसा जीरा","अच्छी बड़ी चुटकी काली मिर्च",["सते सॉस के लिए","1 छोटा प्याज़, कटा हुआ"],["सते सॉस के लिए","2 फांक लहसुन, कुचला हुआ"],["सते सॉस के लिए","1 मिर्च, बारीक कटी हुई"],["सते सॉस के लिए","1 ढेर वाला छोटा चम्मच कॉर्नफ्लोर, 1 बड़े चम्मच पानी में घोला हुआ"],["सते सॉस के लिए","1 बड़ा चम्मच पीनट बटर"],["सते सॉस के लिए","1 छोटा चम्मच कम नमक वाला, ग्लूटेन-मुक्त सोया सॉस"],["सते सॉस के लिए","1 छोटा चम्मच दानेदार स्वीटनर"],["साइड सलाद के लिए","10 सेमी खीरा, माचिस की तीलियों की तरह कतरा हुआ"],["साइड सलाद के लिए","3 हरे प्याज़, माचिस की तीलियों की तरह कतरे हुए"],["साइड सलाद के लिए","1 बड़ा चम्मच कटा हुआ धनिया"],["साइड सलाद के लिए","आधा नींबू (लाइम)"]],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। तेल को बेकिंग शीट पर डालें, सब्ज़ियाँ डालें और जीरा और काली मिर्च छिड़कें और अच्छी तरह मिलाएँ ताकि सारी सब्ज़ियों पर लिपट जाए।","30-40 मिनट बेक करें, बीच में दो-एक बार उलट-पलट करें ताकि बराबर पकें।","इसी बीच, सते सॉस बनाने के लिए, प्याज़ को लहसुन, मिर्च और 150 मिलीलीटर पानी के साथ पैन में डालें और उबाल आने दें। 5 मिनट धीमी आँच पर पकाएँ जब तक प्याज़ नरम न हो जाए। धीरे-धीरे कॉर्नफ्लोर मिलाएँ और तब तक चलाते रहें जब तक गाढ़ा न हो जाए। पीनट बटर, सोया सॉस और स्वीटनर डालें और चिकना होने तक ब्लेंड करें।","सलाद के लिए, खीरे और हरे प्याज़ को मिलाएँ, ऊपर धनिया छिड़कें और परोसने के लिए नींबू का रस निचोड़ें।"],
["ऊपर दिए गए पोषण विश्लेषण में सलाद का परोसने का सुझाव शामिल है।","आप सब्ज़ियों को छोटे टुकड़ों में काटकर सींखों में पिरो सकते हैं और ग्रिल या बारबेक्यू करके सते सॉस और सलाद के साथ परोस सकते हैं।","भुनी हुई जड़ वाली सब्ज़ियों, जैसे कद्दू, सौंफ़ के कंद, चुकंदर के साथ अच्छा लगता है। सते सॉस चिकन के साथ बहुत अच्छी लगती है।","पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फ्रिज या माइक्रोवेव में डीफ़्रॉस्ट करें और अंदर तक अच्छी तरह गरम होने तक दोबारा गरम करें।",fv(3)]))
r.append(R(7500982,"आलू, लीक और चीज़ सूप",
"कम से कम मेहनत वाला यह पौष्टिक व्यंजन झटपट दोपहर के भोजन का एक बढ़िया विकल्प है।",
"2","363 ग्राम",
["1 बड़ा आलू (लगभग 300 ग्राम), कटा हुआ","1 बड़ी लीक, कटी हुई (सजाने के लिए कुछ स्लाइस बचाकर रखें)","600 मिलीलीटर कम नमक वाला वेजिटेबल स्टॉक","50 ग्राम आधी वसा वाला क्रीम चीज़","ताज़ी पिसी काली मिर्च"],
["आलू, लीक और स्टॉक को पैन में डालें।","उबाल आने दें, ढक दें और 15 मिनट धीमी आँच पर पकाएँ जब तक सब्ज़ियाँ नरम न हो जाएँ।","क्रीम चीज़ मिलाएँ, स्वादानुसार नमक-मसाला डालें और चिकना होने तक ब्लेंड करें। परोसने के लिए ऊपर लीक के स्लाइस डालें।"],
["लीक के साथ 2-3 फांक लहसुन डालकर देखें। उन्हें कुचलने की ज़रूरत नहीं क्योंकि आप व्यंजन को ब्लेंड कर रहे हैं।","इस सूप को गहरा हरा रंग देने और सब्ज़ियों की एक अतिरिक्त सर्विंग के लिए, क्रीम चीज़ के साथ मुट्ठी भर डीफ़्रॉस्ट किए हुए फ्रोज़न मटर डालें।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। अच्छी तरह डीफ़्रॉस्ट करें और अंदर तक गरम होने तक दोबारा गरम करें। फ्रीज़ में रहने के दौरान सूप अलग हो सकता है, इसलिए गाढ़ापन बनाए रखने के लिए दोबारा गरम करते समय ज़ोर से चलाएँ।",fv(1)]))
r.append(R(7504418,"स्टेक और शिमला मिर्च की क्वेसाडिया",
"अपने अगले पारिवारिक डिनर के लिए कुछ स्वादिष्ट मैक्सिकन रैप परोसें।",
"4","220 ग्राम",
["कैलोरी-नियंत्रित कुकिंग स्प्रे","175 ग्राम दुबला, पतला कटा स्टेक","1 लाल और 1 पीली शिमला मिर्च, बीज निकालकर कटी हुई","1 लाल प्याज़, कटा हुआ","1 लहसुन की फांक, बारीक कटी हुई","1/2 छोटा चम्मच सूखे मिर्च के गुच्छे (चिली फ्लेक्स)","50 ग्राम आधी वसा वाला चेडर, कद्दूकस किया हुआ","मुट्ठी भर ताज़ी धनिया की पत्तियाँ","4 WW Wraps*"],
["फ्राइंग पैन पर स्प्रे की हल्की फुहार करें और मध्यम आँच पर रखें। स्टेक को हर तरफ़ कम से कम 2 मिनट पकाएँ।","पैन पर फिर से स्प्रे करें, शिमला मिर्च और प्याज़ को 6-8 मिनट पकाएँ। लहसुन और मिर्च डालें और 1 मिनट पकाएँ। स्टेक को पट्टियों में काटें और शिमला मिर्च और प्याज़ में मिलाएँ।","आधा चीज़ 2 रैप पर बिखेरें। ऊपर स्टेक और सब्ज़ियाँ रखें, फिर बचा चीज़ और धनिया डालें। 2 और रैप धीरे से ऊपर दबाएँ। पैन पर फिर से स्प्रे करें और मध्यम आँच पर रखें। एक-एक करके हर तरफ़ 3-4 मिनट पकाएँ, हर बार पैन पर स्प्रे करते हुए। चार टुकड़ों में काटकर परोसें।"],
["*आप अपनी पसंद का कोई भी रैप इस्तेमाल कर सकते हैं, लेकिन याद रखें कि कार्बोहाइड्रेट की मात्रा हर उत्पाद में अलग-अलग हो सकती है।"]))
r.append(R(7505781,"मसालेदार बटरनट स्क्वैश सूप",
"यह स्वादिष्ट सूप गरमाहट देने वाला है और मसाले की तीखी चुभन के साथ आता है।",
"4","380 ग्राम",
["1 बड़ा चम्मच रेपसीड तेल","1 प्याज़, कटा हुआ","1/2–1 लाल मिर्च, कटी हुई","1 फांक लहसुन, कुचला हुआ","2 x मध्यम बटरनट स्क्वैश, छिले, बीज निकाले हुए और कटे हुए","1 बड़ा चम्मच मध्यम करी पेस्ट","1 कम नमक वाला वेजिटेबल स्टॉक क्यूब","200 मिलीलीटर कम वसा वाला नारियल का दूध","2 बड़े चम्मच ताज़ा धनिया, कटा हुआ","ताज़ी पिसी काली मिर्च, परोसने के लिए","कटी हुई मिर्च का एक स्लाइस और धनिया की पत्तियाँ, सजाने के लिए"],
["सॉसपैन में तेल गरम करें। प्याज़, मिर्च और लहसुन डालें, और 4-5 मिनट नरम होने तक भूनें।","स्क्वैश डालें और 5 मिनट भूनते रहें। करी पेस्ट मिलाएँ और 1 मिनट और भूनें।","स्क्वैश के ऊपर 500 मिलीलीटर उबलता पानी डालें, स्टॉक क्यूब को चूरकर डालें और उबाल आने दें। ढक दें और 15-20 मिनट धीमी आँच पर पकाएँ, जब तक स्क्वैश नरम न हो जाए। फूड प्रोसेसर या ब्लेंडर में डालें और चिकना होने तक ब्लेंड करें।","वापस पैन में डालें, नारियल का दूध और धनिया डालें। गरम करें और ऊपर से काली मिर्च छिड़ककर परोसें। मिर्च के एक स्लाइस और हाथ से फाड़ी हुई धनिया की पत्तियों से सजाएँ।"],
["यदि आपको बहुत तीखा पसंद नहीं है, तो मिर्च छोड़ दें और इसकी जगह हल्का करी पेस्ट या पाउडर इस्तेमाल करें।","आप इस सूप को बटरनट स्क्वैश की जगह शकरकंद से बना सकते हैं।","फ्रीज़ करने के निर्देश: सर्विंग के हिसाब से फ्रीज़ करें, फिर फ्रिज में डीफ़्रॉस्ट करें, या माइक्रोवेव में नियमित रूप से चलाने का ध्यान रखते हुए डीफ़्रॉस्ट करें।",fv(3)]))
r.append(R(7511563,"मैकरल रनडाउन",
"यह स्वादिष्ट स्टू जमैकन व्यंजनों का एक क्लासिक है।",
"4","349 ग्राम",
["1 छोटा चम्मच ऑलिव ऑयल","1 बड़ा प्याज़, छिला हुआ और छोटे टुकड़ों में कटा हुआ","2 मोटी लहसुन की फांकें, छिली और कुचली हुई","1 छोटा चम्मच ताज़ी थाइम की पत्तियाँ","1 छोटा चम्मच पपरिका","1 छोटा चम्मच पिसा जीरा","200 मिलीलीटर हल्का नारियल का दूध","2 पके टमाटर, कटे हुए","1 लाल शिमला मिर्च, बीज निकालकर टुकड़ों में कटी हुई","1 पीली शिमला मिर्च, बीज निकालकर टुकड़ों में कटी हुई","1 स्कॉच बोनट मिर्च","3 मैकरल फ़िलेट (प्रत्येक लगभग 90 ग्राम)","एक छोटी मुट्ठी ताज़ा चपटी पत्ती वाला अजमोदा (पार्सले) (वैकल्पिक)"],
["एक बड़े सॉसपैन में तेल गरम करें और प्याज़ को धीमी आँच पर 4–5 मिनट भूनें जब तक नरम न हो जाए लेकिन रंग न बदले। लहसुन, थाइम, पपरिका और जीरा मिलाएँ और लगातार चलाते हुए 30–40 सेकंड भूनें, जब तक खुशबू न आने लगे।","नारियल का दूध, 200 मिलीलीटर पानी, टमाटर, शिमला मिर्च और बटरनट स्क्वैश डालें और अच्छी तरह मिलाएँ।","मिर्च में तेज़ चाकू से कुछ बार छेद करें और फिर उसे नारियल के दूध की सतह के नीचे दबा दें। उबाल आने दें, फिर बिना ढके 15 मिनट धीमी आँच पर पकाएँ।","हर मैकरल फ़िलेट को चार या पाँच टुकड़ों में काटें और सॉस के ऊपर बिखेरें। ढक दें और 10 मिनट और धीमी आँच पर पकाएँ जब तक मछली अंदर तक अच्छी तरह पक न जाए।","स्कॉच बोनट को फेंक दें – या यदि आप साहसी महसूस कर रहे हैं, तो डंठल और बीज फेंक दें, गूदे को मसलें और वापस स्टू में मिला दें। यदि पसंद हो तो अजमोदा बिखेरें, और तुरंत परोसें।"],
[fv(2)]))
r.append(R(7511962,"बनाना ब्रेड",
"अपने पैक्ड लंच में इस फलों वाली ब्रेड का एक स्लाइस रखें।",
"12","58 ग्राम",
["2 बड़े केले (छिले हुए वज़न में 250 ग्राम)","2 फ्री-रेंज अंडे","4 बड़े चम्मच रेपसीड तेल","1 छोटा चम्मच वनीला एसेंस","100 ग्राम नरम हल्की भूरी चीनी","150 ग्राम साबुत गेहूँ का आटा","2 छोटे चम्मच बेकिंग पाउडर","1 ढेर वाला छोटा चम्मच मिक्स्ड स्पाइस","50 ग्राम अखरोट, मोटे कटे हुए (ऊपर रखने के लिए कुछ साबुत बचाकर)"],
["ओवन को 170°C/गैस मार्क 3 पर पहले से गरम करें। केलों को मसलें, फिर अंडे डालें और एक साथ फेंटें।","तेल, वनीला एसेंस और चीनी डालें और अच्छी तरह मिलाएँ।","आटा, बेकिंग पाउडर और मिक्स्ड स्पाइस मिलाएँ, फिर कटे हुए अखरोट धीरे से मिलाएँ।","2 पाउंड की लोफ़ टिन (लगभग 22 x 11 सेमी) में चम्मच से डालें, ऊपर साबुत अखरोट रखें और लगभग 50–55 मिनट बेक करें, जब तक बीच में डाली गई सींक साफ़ न निकले।","जाली पर पूरी तरह ठंडा होने के लिए उलटने से पहले टिन में 10 मिनट ठंडा होने दें।"],
["आप इस मिश्रण में पिसी अदरक या दालचीनी जैसे अन्य मसाले डाल सकते हैं, या अखरोट की जगह बादाम या सूरजमुखी के बीज इस्तेमाल कर सकते हैं।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। स्लाइस करें, फिर फ्रीज़ करने के लिए फ़ॉइल में लपेट दें। फिर ज़रूरत के अनुसार स्लाइस इस्तेमाल कर सकते हैं।"]))
save(5,r)
